from collections import defaultdict


class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_bytes = monthly_limit_mib * 1024 * 1024
        # Maps month -> {filename: size_in_bytes}
        self._uploads: dict[str, dict[str, int]] = defaultdict(dict)
        # Tracks active files per month if deletion needs to remove the file from active set,
        # but quota is tracked by total unique uploaded files.
        self._files: dict[str, set[str]] = defaultdict(set)

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        month_uploads = self._uploads[month]

        # If the file was already uploaded in this month, re-uploading does not count again
        if name in month_uploads:
            self._files[month].add(name)
            return

        current_used = sum(month_uploads.values())
        if current_used + size_bytes > self.monthly_limit_bytes:
            raise ValueError(
                f"Upload of {size_bytes} bytes exceeds remaining quota for {month}."
            )

        month_uploads[name] = size_bytes
        self._files[month].add(name)

    def delete(self, name: str, month: str) -> None:
        """Deletes a file, but does not give back quota in the current month."""
        self._files[month].discard(name)

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._uploads[month].values())
